            mcq("What does DP rely on?", ["Overlapping subproblems and optimal substructure", "Randomness", "Sorting", "Recursion without memory"], 0),
            mcq("LCS of \"ABCBDAB\" and \"BDCABA\" has length…", ["4", "3", "5", "6"], 0),
            fill("Base case: an empty string has LCS length…", "dp[0][j] = ___;", "0"),
